// Der Bauplan braucht betroffene_systeme und tech_stack aus den Potenzialen.
// Seit 22.10.2026 (Vorschlag 7): ohne Potenziale Abbruch statt stillem Ende.
// Sonst liefe BC3-50 ohne Ausgabe durch und BC3-00 merkte es erst später.
const rein = $input.first().json;
const p = rein.umschlag?.potenziale || [];
if (!p.length) throw new Error('BC3-50: keine Potenziale im Umschlag. Lief BC3-10 durch?');
return p.map(x => ({ json: x }));

const u = $('Vom Orchestrator aufgerufen').first().json.umschlag || {};
const t = (u.lieferung?.dateien || []).find(x => x._datei === 'tickets');
if (!t) throw new Error('Keine tickets.json im Umschlag. Lief BC3-40 durch?');
return [{ json: t }];

/**
 * Bauplan erzeugen — Code-Node im BC3-Slicer
 *
 * Erzeugt die architecture.md aus den fertigen Epics und den Angaben zu den
 * betroffenen Systemen. Löst Issue #111.
 *
 * Bewusst OHNE Sprachmodell: Diagramm und Komponententabelle folgen direkt aus
 * den Daten, die schon da sind. Ein LLM könnte hier nur Fehler hinzufügen.
 *
 * Quellen:
 *   - Epics/Stories       aus dem Final-Builder (erstes Item)
 *   - betroffene_systeme  aus "Use Cases extrahieren" (dort stehen sie)
 *   - tech_stack          ebenda
 *
 * Gibt ein Item zurueck, das der Upload-Node zu architecture.md macht.
 */

const tickets = $input.first().json;

// Use-Case-Daten holen - dort stehen Systeme und Tech-Stack
let ucItems = [];
try {
  ucItems = $('Potenziale auspacken').all().map(i => i.json);
} catch (e) {
  ucItems = [];
}

// ---------------------------------------------------------------- Sammeln

// Epics und Use Cases stehen in derselben Reihenfolge: "Use Cases extrahieren"
// gibt sie der Reihe nach aus, der Story-Architekt verarbeitet jedes einzeln,
// "Epics aggregieren" sammelt sie in Eingangsreihenfolge. Über den Index
// lässt sich also zuordnen, welches System zu welchem Epic gehört.
//
// Die Rolle wird JE USE CASE gemerkt, nicht einmal je System. Dasselbe System
// ist oft in einem Schritt Quelle und im nächsten Ziel - die Buchungsdatenbank
// wird in UC1 beschrieben, in UC2 gelesen, in UC3 wieder beschrieben. Die
// früherer Fassung nahm die zuerst gesehene Rolle für alle Schritte; dadurch
// zeigten im Diagramm Pfeile in die falsche Richtung.
const systeme = new Map();   // name -> { integration, verwendetIn[], rollen: Map(epicIdx -> rolle) }
const techStack = new Set();

ucItems.forEach((uc, idx) => {
  for (const t of uc.tech_stack || []) techStack.add(String(t));
  for (const s of uc.betroffene_systeme || []) {
    const name = String(s.name || '').trim();
    if (!name) continue;
    if (!systeme.has(name)) {
      systeme.set(name, { integration: '', verwendetIn: [], rollen: new Map() });
    }
    const eintrag = systeme.get(name);
    if (!eintrag.integration && s.integration) eintrag.integration = s.integration;
    eintrag.verwendetIn.push(uc.use_case_titel || uc.use_case_id);
    eintrag.rollen.set(idx, String(s.rolle || ''));
  }
});

/** Mermaid-Bezeichner: nur Buchstaben und Ziffern, sonst bricht das Diagramm. */
function kennung(praefix, text, i) {
  const rein = String(text).replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  return `${praefix}${i}${rein}`;
}

/** Text für Mermaid-Beschriftungen entschärfen. */
function label(text, max = 40) {
  let s = String(text || '').replace(/["\[\]{}|]/g, '').trim();
  if (s.length > max) s = s.slice(0, max - 1) + '…';
  return s;
}

// ---------------------------------------------------------------- Diagramm

const istQuelle = r => /quelle/i.test(r);
const istZiel = r => /ziel/i.test(r);

const eintraege = [...systeme.entries()];

// Jedes System bekommt GENAU EINEN Knoten, unabhängig davon, in wie vielen
// Rollen es auftritt. Sonst gäbe es denselben Kasten zweimal im Bild.
const knoten = new Map();
eintraege.forEach(([name], i) => knoten.set(name, kennung('s', name, i)));

const rollenVon = v => [...v.rollen.values()];
const nurQuelle = eintraege.filter(([, v]) => rollenVon(v).some(istQuelle) && !rollenVon(v).some(istZiel));
const nurZiel = eintraege.filter(([, v]) => rollenVon(v).some(istZiel) && !rollenVon(v).some(istQuelle));
const beides = eintraege.filter(([, v]) => rollenVon(v).some(istQuelle) && rollenVon(v).some(istZiel));
const sonstige = eintraege.filter(([, v]) => !rollenVon(v).some(istQuelle) && !rollenVon(v).some(istZiel));

const zeilen = ['flowchart LR'];

if (nurQuelle.length) {
  zeilen.push('  subgraph Eingang');
  nurQuelle.forEach(([name]) => zeilen.push(`    ${knoten.get(name)}["${label(name)}"]`));
  zeilen.push('  end');
}

zeilen.push('  subgraph Verarbeitung');
tickets.epics.forEach((e, i) => {
  zeilen.push(`    ${kennung('e', e.titel, i)}["${label(e.titel)}<br/>${e.stories.length} Stories"]`);
});
zeilen.push('  end');

if (nurZiel.length) {
  zeilen.push('  subgraph Ausgang');
  nurZiel.forEach(([name]) => zeilen.push(`    ${knoten.get(name)}["${label(name)}"]`));
  zeilen.push('  end');
}

// Systeme, die gelesen UND beschrieben werden, gehören in keine der beiden
// Seiten - sonst müsste man sie doppelt zeichnen.
if (beides.length || sonstige.length) {
  zeilen.push('  subgraph "Lesend und schreibend"');
  [...beides, ...sonstige].forEach(([name]) => zeilen.push(`    ${knoten.get(name)}["${label(name)}"]`));
  zeilen.push('  end');
}

// Verbindungen: je System und Use Case eine Kante in der Richtung, die dort
// gilt. Quelle -> ins Epic hinein, Ziel -> aus dem Epic heraus.
const epicIds = tickets.epics.map((e, i) => kennung('e', e.titel, i));

for (const [name, v] of eintraege) {
  for (const [idx, rolle] of v.rollen) {
    const epic = epicIds[idx];
    if (!epic) continue;
    // Seit 22.10.2026: ohne Rolle keine Kante, sonst stuende das System als Quelle da
    if (istZiel(rolle)) zeilen.push(`  ${epic} --> ${knoten.get(name)}`);
    if (istQuelle(rolle)) zeilen.push(`  ${knoten.get(name)} --> ${epic}`);
  }
}

// Seit 22.10.2026 (Vorschlag 7): keine Pfeile Epic -> Epic mehr. Die Reihenfolge
// der Epics ist der Rang von BC2, kein Ablauf; ein Pfeil behauptete einen.

const mermaid = zeilen.join('\n');

// ---------------------------------------------------------------- Markdown

const heute = new Date().toISOString().slice(0, 10);
const md = [];

md.push(`# Bauplan — ${tickets.projekt_kurzname}`);
md.push('');
md.push(`**Lieferung:** \`${tickets.lieferung_id}\`  `);
md.push(`**Konzept:** \`${tickets.konzept_ref?.konzept_id ?? 'unbekannt'}\`  `);
md.push(`**Erzeugt am:** ${heute} durch den BC3-Slicer`);
md.push('');
md.push('> Automatisch erzeugt aus dem Ticket-Set. Nicht von Hand ändern —');
md.push('> Änderungen gehen beim nächsten Lauf verloren.');
md.push('');
md.push('## Überblick');
md.push('');
md.push('```mermaid');
md.push(mermaid);
md.push('```');
md.push('');
md.push('Die Epics stehen in der Reihenfolge der Umsetzungsempfehlung von BC2. Das ist kein Ablauf.');
md.push('');

md.push('## Komponenten');
md.push('');
if (systeme.size) {
  // Spalte heisst "Use Case", nicht "Verwendet in": Die Namen stammen aus den
  // Use Cases des Konzepts, während die Abschnitte weiter unten Epic-Titel
  // tragen. Beides ist richtig, las sich aber wie ein Widerspruch.
  md.push('| Komponente | Rolle | Anbindung | Use Case |');
  md.push('|---|---|---|---|');
  for (const [name, v] of [...nurQuelle, ...beides, ...sonstige, ...nurZiel]) {
    const wo = [...new Set(v.verwendetIn)].map(t => label(t, 34)).join(', ');
    // Alle vorkommenden Rollen nennen, nicht nur die erste
    const rollen = [...new Set(rollenVon(v).filter(Boolean))].join(', ');
    md.push(`| ${name} | ${rollen || '—'} | ${v.integration || '—'} | ${wo || '—'} |`);
  }
} else {
  md.push('_Keine Systemangaben im Konzept vorhanden._');
}
md.push('');

if (techStack.size) {
  // Seit 22.10.2026: Angabe von BC2, keine Empfehlung von BC3
  md.push('## Tech-Stack laut Konzept (BC2)');
  md.push('');
  md.push([...techStack].map(t => `- ${t}`).join('\n'));
  md.push('');
}

md.push('## Epics und Stories');
md.push('');
for (const e of tickets.epics) {
  md.push(`### ${e.titel}`);
  md.push('');
  md.push(`\`${e.epic_id}\`  `);
  md.push(`**Ziel:** ${e.ziel}  `);
  if (e.kategorien?.length) md.push(`**Kategorien:** ${e.kategorien.join(', ')}`);
  md.push('');
  md.push('| Story | Titel | Akzeptanzkriterien |');
  md.push('|---|---|---|');
  for (const s of e.stories) {
    const nr = s.story_id.split('-').pop();
    md.push(`| ${nr} | ${label(s.titel, 60)} | ${s.akzeptanzkriterien?.length ?? 0} |`);
  }
  md.push('');
}

const anzahlStories = tickets.epics.reduce((n, e) => n + e.stories.length, 0);
md.push('---');
md.push('');
md.push(`${tickets.epics.length} Epics · ${anzahlStories} Stories · ${systeme.size} Komponenten`);
md.push('');

// --- Zweite Ausgabe: derselbe Bauplan als JSON -----------------------------
// BC4 erwartet seit Juli eine blueprint.json (Backlog C2). Die Daten liegen
// hier schon strukturiert vor, BEVOR Markdown daraus wird - es wäre unsinnig,
// sie später wieder aus dem Markdown herauszulesen.
//
// architecture.md bleibt daneben bestehen: Prüfpunkt 8 an Gate 2 verlangt sie
// wörtlich, GitHub stellt das Mermaid-Diagramm dar, und ein Mensch am Tor
// liest Markdown, kein JSON.
const komponenten = [...systeme.entries()].map(([name, v]) => ({
  name,
  anbindung: v.integration || null,
  rollen: [...new Set(rollenVon(v).filter(Boolean))],
  verwendet_in: [...new Set(v.verwendetIn)],
}));

// Datenflüsse aus den Rollen: was Quelle ist, fliesst in den Prozess hinein,
// was Ziel ist, hinaus. Dieselbe Grundlage wie das Diagramm oben.
const datenfluesse = [];
for (const k of komponenten) {
  for (const r of k.rollen) {
    if (/quelle/i.test(r)) datenfluesse.push({ von: k.name, nach: 'Prozess', art: 'liest' });
    if (/ziel/i.test(r)) datenfluesse.push({ von: 'Prozess', nach: k.name, art: 'schreibt' });
  }
}

// Menschliche Entscheidungspunkte: sie sind der Kern der Artikel-14-Auflage
// und müssen im Bauplan sichtbar sein, nicht nur im Compliance-Befund.
//
// Seit 22.10.2026 (Vorschlag 7): nur noch, wo ein Mensch handelt. Vorher
// zaehlten 'prüf', 'entscheid', 'kontrolle' und 'bestätig' allein - im
// UC1-Lauf 1813 waren so 8 Stories Entscheidungspunkte, darunter
// "Verfügbarkeit prüfen" und "Eingangsbestätigung senden", echt waren 3.
// Beide Schreibweisen, weil ältere Lieferungen ae/ue enthalten koennen.
// "manuell" allein nicht: meist steht es fuer Aufwand, der wegfaellt (UC1-Lauf 1880)
const HANDLUNG = /freigab|freigeb|genehmig|abnahm|vier-augen|(ü|ue)bersteuer|verwerf|anhalten|menschlich|einem? menschen|manuelle[nr]? (pr(ü|ue)fung|bearbeitung|freigabe|entscheidung)|human/i;
// Prüfen, entscheiden, kontrollieren nur, wenn ein Mensch es tut
const MIT_MENSCH = /(mensch|person|teamleitung|sachbearbeit\w*|zust(ä|ae)ndige?)\s+(\S+\s+){0,3}(entscheid|pr(ü|ue)ft|kontrolliert|best(ä|ae)tigt)|(entscheid\w*|pr(ü|ue)fung|kontrolle|best(ä|ae)tigung)\s+(durch|von)\s+(\S+\s+){0,2}(mensch|person|teamleitung|sachbearbeit|zust(ä|ae)ndig)/i;
// "ohne manuelle Zusammenführung" ist das Gegenteil eines Entscheidungspunkts
const OHNE = /(ohne|keine?\w*|nicht)\s+(\S+\s+){0,2}(manuell|menschlich)\w*|(manuell|menschlich)\w*\s+(\S+\s+){0,2}(entf(ä|ae)llt|entfallen|(ü|ue)berfl(ü|ue)ssig)/gi;
const grundVon = text => {
  const t = String(text || '').replace(OHNE, ' ');
  return (t.match(HANDLUNG) || t.match(MIT_MENSCH) || [])[0] || null;
};
const entscheidungspunkte = [];
for (const e of tickets.epics) {
  for (const s of e.stories || []) {
    // Kriterien zaehlen nur, wenn sie einen Menschen nennen (K4: "einem Menschen zugewiesen")
    const kriterien = (s.akzeptanzkriterien || []).map(k => k.text || '').join(' ').replace(OHNE, ' ');
    const grund = grundVon(`${s.titel || ''} ${s.beschreibung || ''}`)
      || (kriterien.match(/einem? menschen|menschlich|manuelle[nr]? (pr(ü|ue)fung|bearbeitung|freigabe|entscheidung)/i) || [])[0] || null;
    if (grund) entscheidungspunkte.push({ story_id: s.story_id, epic_id: e.epic_id, titel: s.titel, erkannt_an: grund });
  }
}

const blueprint = {
  lieferung_id: tickets.lieferung_id,
  projekt_kurzname: tickets.projekt_kurzname,
  kp_id: tickets.konzept_ref?.kp_id || null,
  teilprozess_ids: tickets.konzept_ref?.teilprozess_ids || [],
  erzeugt_am: new Date().toISOString(),
  erzeugt_von: 'BC3-50 Bauplan erzeugen',
  komponenten,
  datenfluesse,
  menschliche_entscheidungspunkte: entscheidungspunkte,
  tech_stack: [...techStack],
  epics: tickets.epics.map(e => ({
    epic_id: e.epic_id,
    titel: e.titel,
    kategorien: e.kategorien || [],
    anzahl_stories: (e.stories || []).length,
  })),
};

return [
  {
    json: {
      _datei: 'architecture',
      _endung: 'md',
      projekt_kurzname: tickets.projekt_kurzname,
      inhalt: md.join('\n'),
      anzahl_komponenten: systeme.size,
    }
  },
  {
    json: {
      _datei: 'blueprint',
      _endung: 'json',
      projekt_kurzname: tickets.projekt_kurzname,
      ...blueprint,
    }
  },
];

// Seit dem Umbau kommen ZWEI Items: architecture.md und blueprint.json.
const ausgaben = $input.all().map(i => i.json);
const arch = ausgaben.find(x => x._datei === 'architecture') || ausgaben[0];
const blueprint = ausgaben.find(x => x._datei === 'blueprint') || null;
const rein = $('Vom Orchestrator aufgerufen').first().json;
const u = rein.umschlag || {};
return [{
  json: {
    lauf_id: rein.lauf_id,
    umschlag: {
      ...u,
      architektur: arch,
      // Nicht ersetzen, sondern ergänzen - sonst gehen andere Felder
      // von lieferung verloren, sobald es welche gibt.
      lieferung: { ...(u.lieferung || {}),
                   dateien: [...(u.lieferung?.dateien || []), ...ausgaben] },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-50 Architektur',
        zeitpunkt: new Date().toISOString(),
        status: 'ok',
        umfang: { komponenten: arch.anzahl_komponenten,
                  entscheidungspunkte: (blueprint?.menschliche_entscheidungspunkte || []).length },
        befunde: blueprint ? [] : ['blueprint.json wurde nicht erzeugt'],
      }],
    },
  },
}];

// Abschluss von BC3-50: der Bauplan ist fertig und liegt im Umschlag.
// API-Abgleich und openapi.yaml sind seit 22.10.2026 abgeschaltet, weil BC4 die openapi.yaml nicht liest.
// Der Hinweis hängt am Protokolleintrag „BC3-50 Architektur“, kein zweiter Eintrag.
const rein = $input.first().json;
const u = rein.umschlag || {};
const prot = [...(u.protokoll || [])];
const satz = 'API-Abgleich und openapi.yaml sind abgeschaltet, BC4 liest die openapi.yaml nicht '
  + '(Entscheidung 15.10.2026).';
const i = prot.map(p => p.stufe).lastIndexOf('BC3-50 Architektur');
if (i >= 0) {
  prot[i] = { ...prot[i], befunde: [...(prot[i].befunde || []), satz] };
} else {
  prot.push({ stufe: 'BC3-50 Architektur', status: 'ok', zeitpunkt: new Date().toISOString(), befunde: [satz] });
}
return [{ json: { ...rein, umschlag: { ...u, protokoll: prot } } }];
